interface Run {
  ch: string;
  n: number;
}

export function solve(chars: string[]): Run[] {
  return chars.reduce<Run[]>((runs, ch) => {
    const last = runs.at(-1);
    if (last !== undefined && last.ch === ch) {
      return [...runs.slice(0, -1), { ch, n: last.n + 1 }];
    }
    return [...runs, { ch, n: 1 }];
  }, []);
}

