export function solve(xs: unknown[], depth: number): unknown[] {
  if (depth <= 0) {
    return xs.slice();
  }
  return xs.reduce<unknown[]>(
    (acc, item) => acc.concat(Array.isArray(item) ? solve(item, depth - 1) : [item]),
    [],
  );
}

