interface TreeNode {
  children: TreeNode[];
  value: number;
}

export function solve(root: TreeNode): number[] {
  const queue: TreeNode[] = [root];
  const values: number[] = [];
  let node = queue.shift();
  while (node !== undefined) {
    values.push(node.value);
    queue.push(...node.children);
    node = queue.shift();
  }
  return values;
}

